#ifndef KV_PPM_IO_HPP
#define KV_PPM_IO_HPP

#include <cstdint>
#include <expected>
#include <iosfwd>
#include <memory>
#include <memory_resource>
#include <span>
#include <string>

#if defined(_WIN32)
#if defined(KV_DYNAMIC_LINK)
#define KV_API __declspec(dllexport)
