}

static void test_alloc_failure(void) {
    reset_alloc_tracking(1);
    FILE* f = make_ppm("P3\n2 2\n255\n0 0 0 255 0 0 0 255 0 0 0 255\n");
    struct PpmResult r = ppm_read_with(f, &kTestAllocator);
